<script setup lang="ts">
import { computed, ref } from 'vue'
import { useExercisesQuery } from '@/api/queries/domainQueries'
import LcCard from '@/components/ui/LcCard.vue'; import LcEmptyState from '@/components/ui/LcEmptyState.vue'; import LcErrorState from '@/components/ui/LcErrorState.vue'; import LcInput from '@/components/ui/LcInput.vue'; import LcSkeleton from '@/components/ui/LcSkeleton.vue'
const search = ref(''); const exercises = useExercisesQuery(); const field = (item: unknown, key: string) => item && typeof item === 'object' ? String((item as Record<string, unknown>)[key] ?? '—') : '—'; const rows = computed(() => (exercises.data.value ?? []).filter((item) => [field(item, 'name'), field(item, 'bodyPart'), field(item, 'formula')].join(' ').toLowerCase().includes(search.value.toLowerCase())))
</script>
<template><section class="grid gap-6"><div><h1 class="font-display text-3xl font-bold">Exercises</h1><p class="mt-2 text-textMuted">Exercise library available to the signed-in coach.</p></div><LcInput v-model="search" label="Search exercises"/><LcSkeleton v-if="exercises.isLoading.value"/><LcErrorState v-else-if="exercises.isError.value" @retry="exercises.refetch()"/><LcEmptyState v-else-if="rows.length === 0" title="No exercises"/><div v-else class="grid gap-3 md:grid-cols-2"><LcCard v-for="exercise in rows" :key="field(exercise, 'id')"><h2 class="font-display text-lg font-bold">{{ field(exercise, 'name') }}</h2><p class="text-sm text-textMuted">Body part: {{ field(exercise, 'bodyPart') }}</p><p class="text-sm text-textMuted">Formula: {{ field(exercise, 'formula') }}</p></LcCard></div></section></template>
